class Solution {
public:
    int minimumNumbers(int num, int k) {
        if (num == 0) return 0;
        for (int s = 1; s <= 10; ++s) {
            if (s * k <= num && (num - s * k) % 10 == 0) {
                return s;
            }
        }
        return -1;
    }
};

